import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BEXTSbmF.js";const u=JSON.parse('{"title":"アプリの入手とインストール","description":"F-Droid や GitHub からのわかりやすいインストール手順","frontmatter":{"title":"アプリの入手とインストール","description":"F-Droid や GitHub からのわかりやすいインストール手順"},"headers":[],"relativePath":"user/installation.md","filePath":"user/installation.md","lastUpdated":1791541899000}'),l={name:"user/installation.md"};function o(s,a,d,n,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="アプリの入手とインストール" tabindex="-1">アプリの入手とインストール <a class="header-anchor" href="#アプリの入手とインストール" aria-label="Permalink to &quot;アプリの入手とインストール&quot;">​</a></h1><p>Palleria は Google Play ストア以外から入手・インストールできます。</p><hr><h2 id="対応環境" tabindex="-1">対応環境 <a class="header-anchor" href="#対応環境" aria-label="Permalink to &quot;対応環境&quot;">​</a></h2><p>Android 7.0（API 24）以降に対応します。x86_64版はIntel / AMD系の対応端末向けです。</p><h2 id="インストール方法" tabindex="-1">インストール方法 <a class="header-anchor" href="#インストール方法" aria-label="Permalink to &quot;インストール方法&quot;">​</a></h2><p>おすすめのインストール方法は <strong>F-Droid リポジトリ</strong> です。更新の検出・通知・インストールの方法はF-Droidクライアントの設定に従います。</p><h3 id="方法-1-f-droid-からインストール-推奨" tabindex="-1">方法 1: F-Droid からインストール (推奨) <a class="header-anchor" href="#方法-1-f-droid-からインストール-推奨" aria-label="Permalink to &quot;方法 1: F-Droid からインストール (推奨)&quot;">​</a></h3><ol><li>スマホに F-Droid アプリ（または Droid-ify 等）をインストールします。</li><li>F-Droid の「設定」&gt;「リポジトリ」を開き、以下の URL を追加します：<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://yunfi.f5.si/Palleria/repo/</span></span></code></pre></div></li><li>リポジトリを更新後、検索画面で <code>Palleria</code> と入力して「インストール」をタップします。</li></ol><hr><h3 id="方法-2-直接ダウンロードしてインストール" tabindex="-1">方法 2: 直接ダウンロードしてインストール <a class="header-anchor" href="#方法-2-直接ダウンロードしてインストール" aria-label="Permalink to &quot;方法 2: 直接ダウンロードしてインストール&quot;">​</a></h3><ol><li><a href="https://github.com/yunfie-twitter/Palleria/releases/latest" target="_blank" rel="noreferrer">GitHub Releases ページ</a> を開きます。</li><li>最新のファイル一覧（Assets）から <code>Palleria-v&lt;バージョン&gt;-release-universal.apk</code>（端末のABIが分かる場合は <code>arm64-v8a</code> / <code>armeabi-v7a</code> / <code>x86_64</code> 版）をタップしてダウンロードします。</li><li>ダウンロードしたファイルを開き、「不明なアプリのインストールを許可」画面が出たら「許可」をオンにしてインストールを完了させます。</li></ol><hr><h2 id="アプリの更新方法" tabindex="-1">アプリの更新方法 <a class="header-anchor" href="#アプリの更新方法" aria-label="Permalink to &quot;アプリの更新方法&quot;">​</a></h2><ul><li><strong>F-Droid から入れた場合</strong>: F-Droid アプリ内で自動または手動で更新できます。</li><li><strong>直接ダウンロードした場合</strong>: アプリ内の「設定」の更新画面から新しいバージョンが配信されているか確認できます。</li></ul>',15)])])}const _=e(l,[["render",o]]);export{u as __pageData,_ as default};
